import bisect
import json
from pathlib import Path


def _unwrap(payload):
    """Unwrap an upstream component wrapper ({'name', 'result'}) to its
    result; otherwise return the payload unchanged."""
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _nonempty_text(x):
    return isinstance(x, str) and x.strip() != ""


def _max_value(sorted_windows, p):
    """Standard weighted interval scheduling over windows already sorted by
    end time. Returns the maximum achievable total value (>= 0)."""
    n = len(sorted_windows)
    if n == 0:
        return 0
    dp = [0] * n
    for i in range(n):
        take = sorted_windows[i]["value"] + (dp[p[i]] if p[i] >= 0 else 0)
        skip = dp[i - 1] if i > 0 else 0
        dp[i] = take if take > skip else skip
    return dp[-1]


def _max_value_constrained(sorted_windows, p, forced, forbidden):
    """Maximum total value using a compatible subset that must include every
    window in `forced` and exclude every window in `forbidden` (sets of
    indices into sorted_windows). Returns None when infeasible."""
    n = len(sorted_windows)
    prev_forced = []
    last = -1
    for i in range(n):
        prev_forced.append(last)
        if i in forced:
            last = i

    dp = [None] * n
    for i in range(n):
        pi = p[i]
        take = None
        base = 0 if pi < 0 else dp[pi]
        if base is not None and prev_forced[i] <= pi:
            take = base + sorted_windows[i]["value"]

        if i in forced:
            dp[i] = take
        elif i in forbidden:
            dp[i] = dp[i - 1] if i > 0 else 0
        else:
            skip = dp[i - 1] if i > 0 else 0
            if skip is None:
                dp[i] = take
            elif take is None:
                dp[i] = skip
            else:
                dp[i] = take if take > skip else skip
    return dp[-1] if n > 0 else 0


def transform(payloads, contract):
    if not payloads:
        raise ValueError("weighted_intervals requires its first input")
    data = _unwrap(payloads[0])

    if not isinstance(data, dict):
        raise ValueError("first input must be an object with a windows list")
    raw_windows = data.get("windows")
    if not isinstance(raw_windows, list):
        raise ValueError("missing or invalid 'windows' list")

    cooldown = contract.get("cooldown")
    if not _is_int(cooldown) or cooldown < 0:
        raise ValueError("cooldown must be an int >= 0")

    windows = []
    seen = set()
    for i, w in enumerate(raw_windows):
        if not isinstance(w, dict):
            raise ValueError("window entry must be an object")
        wid = w.get("id")
        if not _nonempty_text(wid):
            raise ValueError("window id must be non-empty text")
        norm = wid.strip()
        if norm in seen:
            raise ValueError("duplicate window id after stripping: %r" % norm)
        seen.add(norm)
        start = w.get("start")
        end = w.get("end")
        value = w.get("value")
        if not _is_int(start) or start < 0:
            raise ValueError("window start must be an int >= 0")
        if not _is_int(end) or not end > start:
            raise ValueError("window end must be an int > start")
        if not _is_int(value):
            raise ValueError("window value must be an int")
        windows.append({"id": norm, "start": start, "end": end, "value": value})

    n = len(windows)
    if n == 0:
        return {"name": contract["name"], "result": {"selected": [], "value": 0}}

    order = sorted(range(n), key=lambda i: (windows[i]["end"], windows[i]["start"], windows[i]["id"]))
    sorted_windows = [windows[i] for i in order]
    ends = [w["end"] for w in sorted_windows]
    starts = [w["start"] for w in sorted_windows]

    p = []
    for i in range(n):
        target = starts[i] - cooldown
        p.append(bisect.bisect_right(ends, target) - 1)

    best_value = _max_value(sorted_windows, p)
    if best_value == 0:
        return {"name": contract["name"], "result": {"selected": [], "value": 0}}

    id_to_index = {w["id"]: i for i, w in enumerate(sorted_windows)}
    forced = set()
    forbidden = set()
    for wid in sorted(id_to_index):
        idx = id_to_index[wid]
        if _max_value_constrained(sorted_windows, p, forced | {idx}, forbidden) == best_value:
            forced.add(idx)
        else:
            forbidden.add(idx)

    selected = sorted(sorted_windows[i]["id"] for i in forced)
    return {"name": contract["name"], "result": {"selected": selected, "value": best_value}}

