import json, sys, random, itertools
from pathlib import Path
sys.path.insert(0, 'engines/maintenance_windows')
from transform import transform

def brute(windows, cooldown):
    n = len(windows)
    best_val = 0
    best_ids = []
    for mask in range(1 << n):
        chosen = [windows[i] for i in range(n) if mask & (1 << i)]
        # check compatibility
        ok = True
        for a in range(len(chosen)):
            for b in range(len(chosen)):
                if a == b: continue
                x, y = chosen[a], chosen[b]
                if x['start'] < y['start']:
                    if not (x['end'] + cooldown <= y['start']): ok = False
                elif y['start'] < x['start']:
                    if not (y['end'] + cooldown <= x['start']): ok = False
                else:
                    ok = False
        if not ok: continue
        val = sum(w['value'] for w in chosen)
        ids = sorted(w['id'] for w in chosen)
        if val > best_val:
            best_val = val; best_ids = ids
        elif val == best_val:
            if ids < best_ids:
                best_ids = ids
    return best_val, best_ids

def run(windows, cooldown=0):
    payload = {'windows': windows}
    contract = {'name':'maintenance_windows','cooldown':cooldown}
    r = transform([payload], contract)['result']
    return r['value'], r['selected']

random.seed(1)
for t in range(2000):
    n = random.randint(0, 8)
    windows = []
    used = set()
    for i in range(n):
        while True:
            wid = 'w'+str(random.randint(0, 1000))
            if wid not in used: used.add(wid); break
        start = random.randint(0, 20)
        end = start + random.randint(1, 8)
        value = random.randint(-5, 10)
        windows.append({'id': wid, 'start': start, 'end': end, 'value': value})
    cd = random.randint(0, 5)
    bv, bid = brute(windows, cd)
    rv, rid = run(windows, cd)
    if (bv, bid) != (rv, rid):
        print("MISMATCH", t, "cooldown", cd)
        print("windows", windows)
        print("brute", bv, bid)
        print("mine ", rv, rid)
        break
else:
    print("ALL OK")
EOF

