import json
from pathlib import Path


def _unwrap(payload):
    """Unwrap an upstream component wrapper ({'name', 'result'}) to its
    result; otherwise return the payload unchanged."""
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _nonempty_text(x):
    return isinstance(x, str) and x.strip() != ""


def transform(payloads, contract):
    if not payloads:
        raise ValueError("capacity_assignment requires its first input")
    data = _unwrap(payloads[0])

    if not isinstance(data, dict):
        raise ValueError("first input must be an object with jobs and workers")
    raw_jobs = data.get("jobs")
    raw_workers = data.get("workers")
    if not isinstance(raw_jobs, list):
        raise ValueError("missing or invalid 'jobs' list")
    if not isinstance(raw_workers, list):
        raise ValueError("missing or invalid 'workers' list")

    jobs = []
    seen_job = set()
    for j in raw_jobs:
        if not isinstance(j, dict):
            raise ValueError("job entry must be an object")
        jid = j.get("id")
        if not _nonempty_text(jid):
            raise ValueError("job id must be non-empty text")
        if jid.strip() in seen_job:
            raise ValueError("duplicate job id after stripping: %r" % jid)
        seen_job.add(jid.strip())
        skill = j.get("skill")
        if not _nonempty_text(skill):
            raise ValueError("job skill must be non-empty text")
        duration = j.get("duration")
        if not _is_int(duration) or duration < 1:
            raise ValueError("job duration must be an int >= 1")
        jobs.append({"id": jid, "skill": skill, "duration": duration})

    workers = []
    seen_worker = set()
    for w in raw_workers:
        if not isinstance(w, dict):
            raise ValueError("worker entry must be an object")
        wid = w.get("id")
        if not _nonempty_text(wid):
            raise ValueError("worker id must be non-empty text")
        if wid.strip() in seen_worker:
            raise ValueError("duplicate worker id after stripping: %r" % wid)
        seen_worker.add(wid.strip())
        skills = w.get("skills")
        if not isinstance(skills, list):
            raise ValueError("worker skills must be a list")
        for s in skills:
            if not _nonempty_text(s):
                raise ValueError("worker skill must be non-empty text")
        capacity = w.get("capacity")
        if not _is_int(capacity) or capacity < 0:
            raise ValueError("worker capacity must be an int >= 0")
        cost = w.get("cost")
        if not _is_int(cost) or cost < 0:
            raise ValueError("worker cost must be an int >= 0")
        affinity = w.get("affinity")
        if not isinstance(affinity, dict):
            raise ValueError("worker affinity must be an object")
        for v in affinity.values():
            if not _is_int(v):
                raise ValueError("affinity values must be ints")
        workers.append({
            "id": wid,
            "skills": list(skills),
            "capacity": capacity,
            "cost": cost,
            "affinity": affinity,
        })

    # Apply upstream result constraints from subsequent inputs (in order).
    for extra in payloads[1:]:
        res = _unwrap(extra)
        if not isinstance(res, dict):
            continue
        if "selected" in res:
            sel = res["selected"]
            if not isinstance(sel, list):
                raise ValueError("upstream 'selected' must be a list")
            keep = set(sel)
            workers = [w for w in workers if w["id"] in keep]
        if "makespan" in res:
            mk = res["makespan"]
            if not _is_int(mk) or mk < 0:
                raise ValueError("upstream 'makespan' must be an int >= 0")
            for w in workers:
                if w["capacity"] > mk:
                    w["capacity"] = mk

    n = len(jobs)
    if n == 0:
        return {"name": contract["name"], "result": {
            "feasible": True, "score": 0, "cost": 0, "assignments": [],
        }}

    job_ids_sorted = sorted(j["id"] for j in jobs)
    remaining = {w["id"]: w["capacity"] for w in workers}

    best_affinity = None
    best_cost = None
    best_key = None
    best_map = None

    assignment = {}

    def rec(i, aff, cost):
        nonlocal best_affinity, best_cost, best_key, best_map
        if i == n:
            key = tuple(assignment[jid] for jid in job_ids_sorted)
            if (
                best_affinity is None
                or aff > best_affinity
                or (aff == best_affinity and cost < best_cost)
                or (aff == best_affinity and cost == best_cost and key < best_key)
            ):
                best_affinity = aff
                best_cost = cost
                best_key = key
                best_map = dict(assignment)
            return
        job = jobs[i]
        for w in workers:
            if job["skill"] in w["skills"] and remaining[w["id"]] >= job["duration"]:
                remaining[w["id"]] -= job["duration"]
                assignment[job["id"]] = w["id"]
                rec(i + 1, aff + w["affinity"].get(job["id"], 0),
                    cost + w["cost"] * job["duration"])
                del assignment[job["id"]]
                remaining[w["id"]] += job["duration"]

    rec(0, 0, 0)

    if best_map is None:
        return {"name": contract["name"], "result": {
            "feasible": False, "score": 0, "cost": 0, "assignments": [],
        }}

    assignments = [{"job": jid, "worker": best_map[jid]} for jid in job_ids_sorted]
    return {"name": contract["name"], "result": {
        "feasible": True, "score": best_affinity, "cost": best_cost,
        "assignments": assignments,
    }}

