import json
from pathlib import Path


def _unwrap(payload):
    """Unwrap an upstream component wrapper ({'name', 'result'}) to its
    result; otherwise return the payload unchanged."""
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _nonempty_text(x):
    return isinstance(x, str) and x.strip() != ""


def _waves(node_ids, deps_map):
    """Kahn's algorithm returning a list of waves. Each wave is the sorted
    list of node ids that are ready at the start of that wave. Raises
    ValueError on a cycle."""
    indeg = {nid: 0 for nid in node_ids}
    succ = {nid: [] for nid in node_ids}
    for nid, deps in deps_map.items():
        indeg[nid] += len(deps)
        for d in deps:
            succ[d].append(nid)

    waves = []
    processed = 0
    ready = sorted(nid for nid in node_ids if indeg[nid] == 0)
    while ready:
        waves.append(ready)
        processed += len(ready)
        nxt = []
        for nid in ready:
            for s in succ[nid]:
                indeg[s] -= 1
                if indeg[s] == 0:
                    nxt.append(s)
        ready = sorted(nxt)
    if processed != len(node_ids):
        raise ValueError("dependency cycle detected")
    return waves


def _critical_path(node_ids, durations, deps_map):
    waves = _waves(node_ids, deps_map)
    topo = [nid for wave in waves for nid in wave]

    finish = {}
    path = {}
    for nid in topo:
        preds = deps_map[nid]
        dur = durations[nid]
        if not preds:
            finish[nid] = dur
            path[nid] = [nid]
        else:
            maxf = max(finish[p] for p in preds)
            cand = [p for p in preds if finish[p] == maxf]
            best = min(cand, key=lambda p: path[p])
