import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def contracts():
    return sorted(
        p for p in ROOT.rglob("contract.json")
        if "outputs" not in p.relative_to(ROOT).parts
    )


def execution_order(paths):
    """Return contract paths in dependency-first order (topological sort).

    A component depends on another component when one of its declared inputs
    matches that other component's declared output path."""
    output_to_path = {}
    deps = {}
    for p in paths:
        c = json.loads(p.read_text(encoding="utf-8"))
        output_to_path[c["output"]] = p
        deps[p] = []
    for p in paths:
        c = json.loads(p.read_text(encoding="utf-8"))
        for inp in c["inputs"]:
            if inp in output_to_path and output_to_path[inp] != p:
                deps[p].append(output_to_path[inp])

    order = []
    visited = set()
    visiting = set()

    def visit(p):
        if p in visiting:
            raise ValueError("component dependency cycle: %r" % p)
        if p in visited:
            return
        visiting.add(p)
        for d in deps[p]:
            visit(d)
        visiting.remove(p)
        visited.add(p)
        order.append(p)

    for p in paths:
        visit(p)
    return order


def main():
    paths = contracts()
    if not paths:
        raise ValueError("no component contracts found")

    for p in execution_order(paths):
        subprocess.run([sys.executable, str(p.parent / "render.py")], cwd=ROOT, check=True)

    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()

